152	// SafelyAdvanceLocalRef updates localRefName to include targetHash without
153	// dropping local-only commits. Missing and behind refs advance to targetHash;
154	// already-current or locally-ahead refs are left unchanged; diverged refs replay
155	// commits after the merge-base onto targetHash and move localRefName to the
156	// replayed tip. If there is no merge-base and the reachable histories are
157	// complete, the full local chain is replayed.
158	func SafelyAdvanceLocalRef(ctx context.Context, repo *git.Repository, localRefName plumbing.ReferenceName, targetHash plumbing.Hash) error {
159		currentLocal, localErr := repo.Reference(localRefName, true)
160		if localErr != nil {
161			if !errors.Is(localErr, plumbing.ErrReferenceNotFound) {
162				return fmt.Errorf("failed to read local ref %s: %w", localRefName, localErr)
163			}
164			return setRefHash(repo, localRefName, targetHash)
165		}
166	
167		localHash := currentLocal.Hash()
168		if localHash == targetHash {
169			return nil
170		}
171	
172		repoPath, err := getRepoPath(repo)
173		if err != nil {
174			return fmt.Errorf("failed to get repo path: %w", err)
175		}
176	
177		mergeBase, err := getMergeBase(ctx, repoPath, localHash.String(), targetHash.String())
178		if errors.Is(err, errNoMergeBase) {
179			shallow, shallowErr := hasReachableShallowBoundary(ctx, repo, repoPath, localHash.String(), targetHash.String())
180			if shallowErr != nil {
181				return fmt.Errorf("failed to check shallow history for %s: %w", localRefName, shallowErr)
182			}
183			if shallow {
184				return fmt.Errorf("no merge base for %s, and reachable shallow history prevents proving refs are disconnected; run 'entire doctor' or 'git fetch --unshallow' and try again", localRefName)
185			}
186			return replayDisconnectedLocalRef(ctx, repo, repoPath, localRefName, localHash, targetHash)
187		}
188		if err != nil {
189			return fmt.Errorf("failed to find merge base for %s: %w", localRefName, err)
190		}
191		if mergeBase == targetHash {
192			return nil
193		}
194		if mergeBase == localHash {
195			return setRefHash(repo, localRefName, targetHash)
196		}
197	
198		return replayLocalRefFromBase(ctx, repo, repoPath, localRefName, localHash, targetHash, mergeBase)
199	}
