482			return fmt.Errorf("failed to check metadata ref: %w", localErr)
483		}
484		localExists := localErr == nil
485	
486		// A configured checkpoint_remote is the authoritative checkpoint store and
487		// takes precedence over origin's (possibly stale) primary tracking ref. When
488		// it is configured we never seed from origin: a machine migrated from
489		// origin-hosted checkpoints to a dedicated checkpoint_remote must not replay
490		// origin's stale checkpoints into it (issue #1374). The network fetch is
491		// additionally gated on an explicit enable flow (WithCheckpointRemoteBootstrap):
492		// the per-turn hook hot path stays network-free and self-heals via the
493		// empty-orphan fallback.
494		if remote.Configured(ctx) {
495			if localExists {
496				// Heal an un-initialized orphan (empty, or vercel.json-only on a
497				// vercel-enabled repo) from the checkpoint remote. Whatever the
498				// outcome, never fall through to origin.
499				healed, err := healPrimaryFromCheckpointRemote(ctx, repo, localRef, refs.Primary)
500				if err != nil {
501					return err
502				}
503				if healed {
504					fmt.Fprintf(os.Stderr, "✓ Updated local ref '%s' from checkpoint remote\n", primaryName)
505				}
506				return nil
507			}
508			// Local ref missing — fetch the real branch before creating a fresh
509			// orphan: an orphan would diverge from it, hide existing checkpoints, and
510			// be rejected non-fast-forward on later syncs.
511			if bootstrapPrimaryFromCheckpointRemote(ctx, repo, refs.Primary) {
512				fmt.Fprintf(os.Stderr, "✓ Created local ref '%s' from checkpoint remote\n", primaryName)
513				return nil
514			}
515			// Nothing usable on the checkpoint remote (fetch skipped/failed or the
516			// remote has no data) — create a fresh orphan that future pushes publish
517			// there. Still never origin.
518			return createOrphanMetadataRef(ctx, repo, refs)
519		}
